const crypto = require('crypto');

// Signs a call to Convex: HMAC-SHA256 over "timestamp.METHOD.path.body" (see README, Signing).
function signForConvex(path, payload) {
  const secret = $env.LENDLOOP_CONVEX_API_SECRET;
  const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;
  if (!secret || !baseUrl) throw new Error('LENDLOOP_CONVEX_API_SECRET or LENDLOOP_CONVEX_SITE_URL is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const mac = crypto.createHmac('sha256', secret).update(timestamp + '.POST.' + path + '.' + body).digest('hex');
  return { url: baseUrl + path, body, timestamp, signature: 'v1=' + mac };
}

// Works for both shapes n8n sends: a failed execution, or a trigger that failed to start.
const { execution = {}, workflow = {}, trigger } = $input.first().json;
const error = execution.error || (trigger && trigger.error) || {};
const message = String(error.message || 'Unknown error').slice(0, 500);
const executionId = String(execution.id || 'trigger-' + (workflow.id || 'unknown') + '-' + Date.now());
const nodeName = execution.lastNodeExecuted || (error.node && error.node.name) || undefined;

console.error('[lendloop] workflow failed: ' + (workflow.name || workflow.id) + ' execution=' + executionId
  + ' node=' + (nodeName || '-') + ': ' + message);

return [{ json: signForConvex('/automation/failures', {
  executionId,
  workflowName: workflow.name || 'unknown',
  nodeName,
  message,
}) }];
